// Trae todas las páginas del maestro "branches" de Pilot
const token = $('Login1').first().json.result.entitydata.session.identityToken;
const url = 'https://api.pilotsolution.net/v1/masters/read.php';

const pedir = (page) =>
  this.helpers.httpRequest({
    method: 'POST',
    url,
    json: true,
    body: {
      data: { master: 'branches', limit: 100, page },
      header: {
        FlowName: 'masterdata_read',
        SequenceId: 1,
        TimeStamp: 1248377,
        TrackingId: '55A6BCD4-0857-4A86-85FB-09A228B641B4',
        access_token: token,
      },
    },
  });

const primera = await pedir(1);
if (primera?.result?.status !== 'success') {
  return [{ json: { ok: false, error: primera?.result?.message || 'Error al consultar las sucursales', respuesta: primera } }];
}

const info = primera.result.aditional_data || {};
const paginas = Number(info.page_count) || 1;
const filas = [...(primera.result.entitydata || [])];

for (let p = 2; p <= paginas; p++) {
  const r = await pedir(p);
  if (r?.result?.status !== 'success') break;
  filas.push(...(r.result.entitydata || []));
}

// Sin repetidos (por si la API ignora el número de página)
const vistos = new Set();
const unicas = filas.filter((s) => {
  const k = s.id ?? s.code;
  if (vistos.has(k)) return false;
  vistos.add(k);
  return true;
});

return [{ json: { ok: true, rows_count: Number(info.rows_count) || unicas.length, paginas, sucursales_raw: unicas } }];

// Deja la información relevante de cada sucursal
const norm = (s) => String(s ?? '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9]+/g, '');

let buscado = '';
try { buscado = String($('When Executed by Another Workflow').first().json.sucursal ?? ''); } catch (e) { buscado = ''; }
const q = norm(buscado);

const r = $input.first().json;
if (!r.ok) return [{ json: r }];

const txt = (v) => (v === null || v === undefined ? '' : String(v).trim());

const todas = r.sucursales_raw
  .filter((s) => String(s.deleted) !== '1' && String(s.visible) !== '0')
  .map((s) => ({
    id: s.id,
    codigo: txt(s.code),
    nombre: txt(s.name),
    empresa: txt(s.company?.name),
    tipo: txt(s.branch_type?.branch_type_name),
    marca: txt(s.commercial_brand?.name),
    direccion: txt(s.address),
    telefono: txt(s.phone),
    latitud: s.address_latitude ?? null,
    longitud: s.address_longitude ?? null,
  }));

const sucursales = q
  ? todas.filter((s) => norm(s.nombre).includes(q) || norm(s.codigo).includes(q) || norm(s.empresa).includes(q))
  : todas;

return [{
  json: {
    ok: true,
    buscado,
    total_en_pilot: r.rows_count,
    total_traidas: todas.length,
    completo: todas.length >= r.rows_count,
    total: sucursales.length,
    sucursales,
  },
}];

